<div class="mt-4 grid grid-cols-2 gap-2"><label class="rounded-xl border p-3"><input type="radio" name="type" value="money" x-model="type"> <b>Uang</b></label><label class="rounded-xl border p-3"><input type="radio" name="type" value="gift" x-model="type"> <b>Hadiah</b></label></div><label x-show="type==='money'" class="mt-3 block"><span class="text-sm font-bold">Nominal Rupiah *</span><input name="amount" inputmode="numeric" pattern="[0-9]*" :value="{{ ($editing??false) ? "selected?.amount" : "''" }}" :required="type==='money'" class="mt-1 w-full rounded-xl border-slate-300" placeholder="Contoh: 100000"></label><label x-show="type==='gift'" class="mt-3 block"><span class="text-sm font-bold">Deskripsi hadiah *</span><textarea name="gift_description" :value="{{ ($editing??false) ? "selected?.gift_description" : "''" }}" :required="type==='gift'" rows="3" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label><label class="mt-3 block"><span class="text-sm font-bold">Catatan</span><textarea name="notes" :value="{{ ($editing??false) ? "selected?.notes" : "''" }}" rows="3" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label>
